:where([data-moru-registry]) .ui-file-input {
  --ui-file-height: var(--ui-control-height-md, 40px);
  --ui-file-padding-x: var(--ui-control-padding-x-md, 12px);
  --ui-file-icon: var(--ui-icon-size-md, 16px);
  --ui-file-inset: var(--ui-space, 4px);
  --ui-file-border: var(--ui-border-width, 1px);
  --ui-file-resolved-height: max(
    var(--ui-file-height),
    calc(
      max(
          var(--ui-type-label-size, 14px) * var(--ui-type-label-line-height, 1.45),
          var(--ui-file-icon)
        ) +
        var(--ui-file-inset) * 2 + var(--ui-file-border) * 2
    )
  );
  --ui-file-button-height: calc(
    var(--ui-file-resolved-height) - var(--ui-file-inset) * 2 - var(--ui-file-border) * 2
  );
  display: grid;
  gap: var(--ui-field-gap, 8px);
  min-width: 0;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-label-size);
  line-height: var(--ui-type-label-line-height);
  letter-spacing: var(--ui-type-label-letter-spacing);
}
:where([data-moru-registry]) .ui-file-input input[type='file'] {
  box-sizing: border-box;
  display: block;
  width: 100%;
  min-width: 0;
  height: var(--ui-file-resolved-height);
  min-height: var(--ui-file-resolved-height);
  padding: var(--ui-file-inset);
  font: inherit;
  letter-spacing: inherit;
  line-height: var(--ui-file-button-height);
  border: var(--ui-border-width, 1px) solid var(--ui-control-border, var(--ui-border, #8a8a86));
  border-radius: var(--ui-radius);
  background: var(--ui-input-bg);
  color: var(--ui-muted);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-file-input input[type='file']:not(:disabled):not([aria-invalid='true']):hover {
  border-color: var(--ui-control-hover-border, var(--ui-control-border, #8a8a86));
  background: var(--ui-control-hover-bg, var(--ui-input-bg));
}
:where([data-moru-registry]) .ui-file-input[data-size='sm'] {
  --ui-file-height: var(--ui-control-height-sm, 32px);
  --ui-file-padding-x: var(--ui-control-padding-x-sm, 10px);
  --ui-file-icon: var(--ui-icon-size-sm, 14px);
}
:where([data-moru-registry]) .ui-file-input[data-size='lg'] {
  --ui-file-height: var(--ui-control-height-lg, 48px);
  --ui-file-padding-x: var(--ui-control-padding-x-lg, 16px);
  --ui-file-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-file-input input[type='file']::file-selector-button {
  box-sizing: border-box;
  height: var(--ui-file-button-height);
  min-height: 0;
  margin: 0;
  margin-inline-end: var(--ui-control-gap, 8px);
  padding: 0 var(--ui-file-padding-x);
  vertical-align: top;
  border: 0;
  border-radius: max(0px, calc(var(--ui-radius) - var(--ui-file-inset)));
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  cursor: pointer;
}
:where([data-moru-registry]) .ui-file-input input[type='file']:not(:disabled):hover::file-selector-button {
  background: var(--ui-control-hover-bg);
}
:where([data-moru-registry]) .ui-file-input input[type='file']:focus-visible {
  outline: 2px solid var(--ui-focus-ring, var(--ui-primary, #181818));
  outline-offset: 2px;
}
:where([data-moru-registry]) .ui-file-input input[type='file'][aria-invalid='true'] {
  outline-color: var(--ui-error-ring, var(--ui-danger));
  border-color: var(--ui-danger);
  background: var(--ui-danger-soft, #f9efef);
  box-shadow: 0 0 0 1px var(--ui-error-ring, var(--ui-danger));
}
:where([data-moru-registry]) .ui-file-input input[type='file']:disabled {
  background: var(--ui-disabled-bg);
  color: var(--ui-disabled-text);
  box-shadow: none;
}
:where([data-moru-registry]) .ui-file-input[data-disabled]:not([data-loading]) {
  opacity: 0.55;
}
:where([data-moru-registry]) .ui-file-input[data-loading] input[type='file'] {
  padding-inline-end: calc(
    var(--ui-size-icon, var(--ui-icon-size-md, 16px)) + var(--ui-control-gap, 8px) * 2
  );
  cursor: progress;
}
:where([data-moru-registry]) .ui-file-input-selection {
  display: flex;
  align-items: flex-start;
  gap: var(--ui-field-gap, 8px);
  min-width: 0;
}
:where([data-moru-registry]) .ui-file-input-selection ul {
  display: grid;
  flex: 1;
  gap: var(--ui-field-gap, 8px);
  min-width: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}
:where([data-moru-registry]) .ui-file-input-selection li {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--ui-space, 4px) var(--ui-control-gap, 8px);
  min-width: 0;
  min-height: var(--ui-file-resolved-height);
  padding: calc(var(--ui-space, 4px) * 2) var(--ui-file-padding-x);
  border: var(--ui-file-border) solid var(--ui-border);
  border-radius: var(--ui-radius);
  background: var(--ui-surface);
}
:where([data-moru-registry]) .ui-file-input-selection li > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-file-input-selection small {
  color: var(--ui-muted);
  font-size: var(--ui-type-caption-size);
  font-variant-numeric: tabular-nums;
}
:where([data-moru-registry]) .ui-file-input-selection button {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  flex: none;
  width: max(28px, var(--ui-file-resolved-height));
  min-height: max(28px, var(--ui-file-resolved-height));
  padding: var(--ui-space, 4px);
  border: 0;
  border-radius: var(--ui-radius);
  background: transparent;
  color: var(--ui-muted);
}
:where([data-moru-registry]) .ui-file-input-selection button > svg {
  width: var(--ui-file-icon);
  height: var(--ui-file-icon);
}
:where([data-moru-registry]) .ui-file-input-selection button:hover:not(:disabled) {
  background: var(--ui-control-hover-bg);
  color: var(--ui-text);
}
:where([data-moru-registry]) .ui-file-input-error {
  margin: 0;
  color: var(--ui-danger-surface-text, var(--ui-danger));
  font-size: var(--ui-type-caption-size);
  line-height: var(--ui-type-caption-line-height);
  overflow-wrap: anywhere;
}
@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-file-input {
    --ui-file-resolved-height: max(
      44px,
      var(--ui-file-height),
      calc(
        max(
            max(16px, var(--ui-type-label-size, 14px)) * var(--ui-type-label-line-height, 1.45),
            var(--ui-file-icon)
          ) +
          var(--ui-file-inset) * 2 + var(--ui-file-border) * 2
      )
    );
  }
}
@media (forced-colors: active) {
  :where([data-moru-registry]) .ui-file-input {
    --ui-file-border: 1px;
  }
  :where([data-moru-registry]) .ui-file-input input[type='file'] {
    border: var(--ui-file-border) solid ButtonText;
  }
}

:where([data-moru-registry]) .ui-file-input-selection button:disabled {
  color: var(--ui-disabled-text);
  cursor: not-allowed;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import {
  forwardRef,
  useEffect,
  useId,
  useImperativeHandle,
  useRef,
  useState,
  type ChangeEvent,
  type InputHTMLAttributes,
} from 'react'
import { X } from 'lucide-react'
import { Input as BaseInput } from '@base-ui/react/input'
import { cn } from './_lib/cn'
import { formatFileSize } from './attachment'
import { mergeDescriptionIds, useFieldContext } from './field-context'
import { validateFiles } from './file-input-utils'
import type { UIState } from './state'
import './file-input.css'

export interface FileInputProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'type' | 'value' | 'defaultValue' | 'size'
> {
  size?: 'sm' | 'md' | 'lg'
  loading?: boolean
  previewState?: UIState
  maxSize?: number
  maxFiles?: number
  onFilesChange?: (files: File[]) => void
}

/** Real file selection only. Uploading and server-side validation remain the consumer's responsibility. */
export const FileInput = forwardRef<HTMLInputElement, FileInputProps>(function FileInput(
  {
    className,
    id,
    size = 'md',
    maxSize,
    maxFiles,
    onFilesChange,
    onChange,
    disabled,
    loading = false,
    previewState,
    'aria-describedby': describedBy,
    'aria-invalid': invalid,
    ...props
  },
  ref,
) {
  const { t, formatLocale } = useI18n()

  const field = useFieldContext()
  const generatedId = useId()
  const inputRef = useRef<HTMLInputElement>(null)
  const [files, setFiles] = useState<File[]>([])
  const [error, setError] = useState<string | null>(null)
  const busy = loading || previewState === 'loading'
  const unavailable = disabled || busy || previewState === 'disabled'
  useImperativeHandle(ref, () => inputRef.current!, [])
  useEffect(() => {
    const form = inputRef.current?.form
    if (!form) return
    let subscribed = true
    function reset(event: Event) {
      queueMicrotask(() => {
        if (subscribed && !event.defaultPrevented) {
          setFiles([])
          setError(null)
        }
      })
    }
    form.addEventListener('reset', reset)
    return () => {
      subscribed = false
      form.removeEventListener('reset', reset)
    }
  }, [props.form])
  const errorId = `${generatedId}-file-error`
  function change(event: ChangeEvent<HTMLInputElement>) {
    if (unavailable) return
    const selected = Array.from(event.currentTarget.files ?? [])
    const message = validateFiles(selected, { accept: props.accept, maxSize, maxFiles })
    setError(message)
    if (message) event.currentTarget.value = ''
    const next = message ? [] : selected
    setFiles(next)
    onFilesChange?.(next)
    onChange?.(event)
  }
  return (
    <div
      className={cn('ui-file-input', className)}
      data-size={size}
      data-disabled={unavailable || undefined}
      data-loading={busy || undefined}
    >
      <span className="ui-control-loading-wrap" data-size={size}>
        <BaseInput
          {...props}
          ref={inputRef}
          id={id ?? field?.controlId ?? generatedId}
          type="file"
          disabled={unavailable}
          aria-busy={busy || undefined}
          aria-invalid={
            previewState === 'error'
              ? true
              : (invalid ?? (Boolean(error) || field?.invalid || undefined))
          }
          aria-describedby={mergeDescriptionIds(
            describedBy,
            field?.describedBy,
            error ? errorId : undefined,
          )}
          onChange={change}
        />
        {busy && (
          <span className="ui-control-loading-indicator ui-loading-indicator" aria-hidden="true" />
        )}
      </span>
      {files.length ? (
        <div className="ui-file-input-selection">
          <ul aria-label={t('선택한 파일')}>
            {files.map((file, index) => (
              <li key={`${file.name}-${index}`}>
                <span>{file.name}</span>
                <small>{t(formatFileSize(file.size, formatLocale))}</small>
              </li>
            ))}
          </ul>
          <button
            type="button"
            disabled={unavailable}
            aria-label={t('선택한 파일 모두 지우기')}
            onClick={() => {
              if (unavailable) return
              if (inputRef.current) inputRef.current.value = ''
              setFiles([])
              setError(null)
              onFilesChange?.([])
              inputRef.current?.focus()
            }}
          >
            <X size={14} aria-hidden="true" />
          </button>
        </div>
      ) : null}
      {error ? (
        <p className="ui-file-input-error" role="alert" id={errorId}>
          {error}
        </p>
      ) : null}
    </div>
  )
})
